+++ b/Users/dev/.bb/plugins/environment-git-worktree/host-data/worktrees/thr_tzb6pnfr3t-1/rewind-playground/lib/format.js
+/**
+ * Format a task as a single-line string.
+ * @param {{ id: number, text: string, priority?: string, done?: boolean }} task
+ * @returns {string}
+ */
+function formatTask(task) {
+  const check = task.done ? "x" : " ";
+  const priority = task.priority || "medium";
+  return `${task.id} [${check}] (${priority}) ${task.text}`;
+}
+
+module.exports = { formatTask };

